def pairwise_address_similarity(
    X: Sequence[str],
    Y: Sequence[str] | None = None,
    *,
    metric: Literal["hybrid", "token", "levenshtein", "street"] | str = "hybrid",
    alpha: float = 0.70,
    normalize: bool = True,
) -> NDArray[np.float32]:
    """Compute pairwise address similarity matrix adhering to scikit-learn pairwise kernel conventions.

    Args:
        X: Sequence of address strings of length N.
        Y: Optional sequence of address strings of length M. If None, computes pairwise similarity
           of X against itself (symmetric N x N).
        metric: Similarity metric to use: 'hybrid' (blended token + Levenshtein),
                'token' (token set ratio), 'levenshtein' (raw Levenshtein edit ratio),
                or 'street' (street name similarity with digit lock).
        alpha: Weight for token similarity when metric='hybrid' (default: 0.70).
        normalize: If True (default), normalizes scores to range [0.0, 1.0].
                   If False, returns raw percentage scores [0.0, 100.0].

    Returns:
        2D numpy array of shape (len(X), len(Y or X)) with float32 similarity values.
    """
    if len(X) == 0:
        y_len = len(X) if Y is None else len(Y)
        return np.zeros((0, y_len), dtype=np.float32)

    norm_x = [normalize_ascii(x).strip(" ,-") for x in X]
    norm_y = norm_x if Y is None else [normalize_ascii(y).strip(" ,-") for y in Y]

    if len(norm_y) == 0:
        return np.zeros((len(norm_x), 0), dtype=np.float32)

    if metric == "token":
        raw = np.asarray(
            process.cdist(norm_x, norm_y, scorer=fuzz.token_set_ratio),
            dtype=np.float32,
        )
    elif metric == "levenshtein":
        raw = np.asarray(
            process.cdist(norm_x, norm_y, scorer=fuzz.ratio),
            dtype=np.float32,
        )
    elif metric == "hybrid":
        raw_token = np.asarray(
            process.cdist(norm_x, norm_y, scorer=fuzz.token_set_ratio),
            dtype=np.float32,
        )
        raw_lev = np.asarray(
            process.cdist(norm_x, norm_y, scorer=fuzz.ratio),
            dtype=np.float32,
        )
        raw = (alpha * raw_token + (1.0 - alpha) * raw_lev).astype(np.float32)
    elif metric == "street":
        x_list = list(X)
        y_list = x_list if Y is None else list(Y)
        raw = np.empty((len(x_list), len(y_list)), dtype=np.float32)
        if Y is None:
            n = len(x_list)
            for i in range(n):
                raw[i, i] = evaluate_street_similarity(x_list[i], x_list[i])
                for j in range(i + 1, n):
                    s = evaluate_street_similarity(x_list[i], x_list[j])
                    raw[i, j] = s
                    raw[j, i] = s
        else:
            for i, x in enumerate(x_list):
                for j, y in enumerate(y_list):
                    raw[i, j] = evaluate_street_similarity(x, y)
        return raw if normalize else (raw * 100.0).astype(np.float32)
    else:
        raise ValueError(
            f"Unknown metric {metric!r}. Expected 'hybrid', 'token', 'levenshtein', or 'street'."
        )

    return (raw / 100.0).astype(np.float32) if normalize else raw
